import os
import shutil
from datetime import date
from decimal import Decimal

from pyspark.sql import functions as F


def start_table(invoices, path):
    # Last night's Delta table, with two invoices. Don't change this.
    shutil.rmtree(path, ignore_errors=True)  # start from an empty folder on every run
    last_night = spark.createDataFrame(
        [
            ("INV-000001", "ACC-0001", date(2025, 10, 14), date(2025, 11, 13), "open", Decimal("244.00")),
            ("INV-000090", "ACC-0004", date(2025, 9, 30), date(2025, 10, 30), "void", Decimal("99.00")),
        ],
        invoices.schema,
    )
    last_night.write.format("delta").save(path)


def write_tonights_file(invoices, folder):
    # Tonight's export from the billing system. Don't change this.
    shutil.rmtree(folder, ignore_errors=True)
    os.makedirs(folder)

    def text(value):
        if value is None:
            return ""
        if isinstance(value, date):
            return value.strftime("%d/%m/%Y")  # day/month/year
        return str(value)

    lines = ["invoice_id;account_id;invoice_date;due_date;status;total_amount"]
    for row in invoices.collect():
        lines.append(";".join(text(v) for v in row))
    with open(folder + "/invoices.csv", "w") as f:
        f.write("\n".join(lines) + "\n")


def load_file(folder):
    # Read tonight's file with the table's column types.
    return spark.read.csv(folder, header=True)


def save(df, path):
    # Replace the table with tonight's invoices.
    df.write.format("delta").mode("overwrite").save(path)


def solve(invoices):
    path = "/tmp/billing/invoices"
    folder = "/tmp/billing/incoming"
    start_table(invoices, path)
    write_tonights_file(invoices, folder)
    save(load_file(folder), path)
    return spark.read.format("delta").load(path)
